import {LEADER_FORTS,FORT_STONE_BOARD,FORT_SYMBOLS,fortForRoom} from './leader-fort-data.js?v=0.90.48';
import {fortBoardWall,fortBoardContains,leaderFortState,fortGateOpen} from './leader-fort-rules.js?v=0.90.20';
export function installLeaderForts(maps){for(const f of LEADER_FORTS){const town=maps[f.town];town.spots=town.spots.filter(s=>s.id!==f.leaderSpot);town.gates.push({id:f.door,label:f.name,x:f.entrance[0],y:f.entrance[1],to:f.room,arrival:[4,17,'right'],action:'leader-fort-entry',door:true});maps[f.room]={name:f.name,terrain:'fort',leaderFort:f.key,caveFloor:0,bloom:true,road:[],grass:[],props:[{asset:'shelf',x:4,y:7,w:3,h:2},{asset:'table',x:5,y:25,w:4,h:2},{asset:'shelf',x:27,y:7,w:3,h:2},{asset:'table',x:31,y:25,w:3,h:2}],spots:[{id:f.key+'-fort-sign',label:'Fort challenge notice',x:5,y:21},{id:f.key+'-mechanism',label:f.kind==='stones'?'Counterweight plaque · clue and reset':'Chapter mosaic · ring controls',x:14,y:23,wallSign:true},...(['symbols','scales'].includes(f.kind)?[{id:'fort-ring-0',label:'Turn left ring',x:17,y:12},{id:'fort-ring-1',label:'Turn middle ring',x:20,y:12},{id:'fort-ring-2',label:'Turn right ring',x:23,y:12}]:[]),...f.guardIds.map((id,n)=>({id,label:f.guards[n],x:[8,29,33][n],y:[14,13,22][n],sprite:2,patrol:[[[8,14],[8,17]],[[29,13],[29,17]],[[33,22],[33,18]]][n]})),{id:f.key+'-fort-cache',label:'Inner-watch provision chest',x:29,y:25},{id:f.leaderSpot,label:f.leaderName,x:41,y:17,sprite:0}],gates:[{id:'room-exit',label:'Return to '+f.town,x:1,y:17,to:f.town,arrival:f.return,door:true}]};}}
export function leaderFortWalkable(m,x,y){if(!m.leaderFort)return null;if(x===1&&y===17)return true;if(x<2||x>45||y<6||y>28)return false;if([12,25,36].includes(x))return y>=16&&y<=18;if(m.leaderFort==='dorelem'&&fortBoardContains(x,y))return !fortBoardWall(x,y);return true;}
const fill=(c,color,x,y,w,h)=>{c.fillStyle=color;c.fillRect(x,y,w,h);};
function symbol(c,n,x,y,size=14){const s=FORT_SYMBOLS[n];c.strokeStyle=s.color;c.fillStyle=s.color;c.lineWidth=2;c.beginPath();if(n===0){c.arc(x+size/2,y+size/2,size*.24,0,Math.PI*2);c.stroke();for(const [dx,dy]of [[0,-1],[0,1],[-1,0],[1,0]])fill(c,s.color,x+size/2+dx*size*.4-1,y+size/2+dy*size*.4-1,2,2);}if(n===1){c.arc(x+size/2,y+size/2,size*.36,.6,5.7);c.stroke();}if(n===2){c.moveTo(x+2,y+size-2);c.quadraticCurveTo(x+size,y+size,x+size-2,y+2);c.quadraticCurveTo(x,y,x+2,y+size-2);c.stroke();c.moveTo(x+2,y+size-2);c.lineTo(x+size-2,y+2);c.stroke();}if(n===3){for(let i=0;i<2;i++){c.moveTo(x,y+3+i*6);c.quadraticCurveTo(x+size/2,y-1+i*6,x+size,y+3+i*6);}c.stroke();}}
export function drawLeaderFortDecor(c,m,asset){if(!m.leaderFort)return;c.save();for(const x of [12,25,36])for(let y=6;y<=28;y++)if(y<16||y>18){fill(c,'#4a5053',x*16,y*16,16,16);if(asset)asset(c,'fortWall',x,y,1,1);fill(c,'#121c2844',x*16,y*16,16,16);fill(c,'#a4a28e',x*16+2,y*16,12,2);}for(const [x,y]of [[7,7],[28,7],[39,7]])if(asset)asset(c,'fortBanner',x,y,1.5,3);if(asset)asset(c,'fortCarpet',39,13,5,9);if(asset)asset(c,'table',40,15,2,1.2);
 for(const x of [12,25,36]){fill(c,'#b3aa8a',x*16-4,16*16-6,24,6);fill(c,'#767a6d',x*16-3,19*16,22,3);}
 const f=LEADER_FORTS.find(f=>f.key===m.leaderFort);if(['symbols','scales'].includes(f.kind)){fill(c,'#352f3d',16*16,8*16,8*16,32);f.target.forEach((n,i)=>{if(f.kind==='scales'){c.fillStyle='#dfbd70';c.font='bold 20px sans-serif';c.fillText(String(n),(17+i*3)*16,8*16+25);}else symbol(c,n,(17+i*3)*16,8*16+8,18);});for(const x of [17,20,23]){fill(c,'#515e5b',x*16-3,12*16-5,22,22);fill(c,'#bcb292',x*16-3,12*16-5,22,3);}}c.restore();}
export function drawLeaderFortState(c,state,room,asset){const f=fortForRoom(room);if(!f)return;const p=leaderFortState(state,f.key);c.save();for(const [i,x]of [12,25,36].entries()){const open=fortGateOpen(state,f,i);if(open){fill(c,'#719688',x*16+4,16*16-5,8,3);continue;}if(asset)asset(c,'fortGate',x,16,1,3);else {fill(c,'#302f36',x*16,16*16,16,48);for(let a=2;a<16;a+=4)fill(c,'#a09b87',x*16+a,16*16,2,48);}}
 if(f.kind==='stones'){for(const [x,y]of FORT_STONE_BOARD.goals){fill(c,'#45685d',x*16+1,y*16+1,14,14);symbol(c,2,x*16+2,y*16+2,12);}for(const [x,y]of p.stones){if(asset)asset(c,'fortStone',x,y,1,1);else {fill(c,'#444d50',x*16,y*16+3,16,13);fill(c,'#a3a58a',x*16+1,y*16+1,14,11);symbol(c,2,x*16+4,y*16+4,8);}}}
 else p.rings.forEach((n,i)=>{if(f.kind==='scales'){c.fillStyle='#dfbd70';c.font='bold 18px sans-serif';c.fillText(String(n),(17+i*3)*16,12*16+16);}else symbol(c,n,(17+i*3)*16,12*16,16);});
 c.restore();}

export function drawLeaderFortEntrances(c,m,asset){for(const g of m.gates.filter(g=>g.action==='leader-fort-entry')){if(asset)asset(c,'fortArch',g.x-.5,g.y-2,2,3);}}
